package site.cadera.arunika.dungeon.paper;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.bukkit.*;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import net.kyori.adventure.text.Component;
import site.cadera.arunika.dungeon.config.SnakeYamlCodec;
import site.cadera.arunika.dungeon.exchange.*;
import site.cadera.arunika.dungeon.exchange.ExchangeCatalog.*;
import site.cadera.arunika.dungeon.privategame.TicketLedger;
/** Staging-only Exchange. Bukkit state stays on main thread; a bounded worker owns SQLite. */
final class PaperExchange implements Listener,AutoCloseable {
 private final ArunikaDungeonPlugin plugin;private final Path root,live,settingsFile;private final TicketLedger ticketLedger;private PaperTickets tickets;
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(128),r->{Thread t=new Thread(r,"ArunikaExchange-SQLite");t.setDaemon(true);return t;}){ @Override protected void terminated(){closeDatabase();} };
 private final Set<UUID> busy=new HashSet<>();private boolean editing,enabled;private volatile boolean closed;private String status="Starting";private Catalog catalog;private ItemStack token;private Map<UUID,ItemStack> previews=Map.of();private ExchangeLedger db;
 private final SnakeYamlCodec codec=new SnakeYamlCodec();
 private record Loaded(Catalog catalog,boolean enabled){}
 private static final class Menu implements InventoryHolder{final UUID owner;final String category;final int page;final UUID confirm;boolean clickPending;final Map<Integer,Reward> slots=new HashMap<>();Inventory inv;Menu(UUID owner,String category,int page,UUID confirm){this.owner=owner;this.category=category;this.page=page;this.confirm=confirm;}public Inventory getInventory(){return inv;}}
 PaperExchange(ArunikaDungeonPlugin plugin,TicketLedger ledger,String material,String name){this.plugin=plugin;root=plugin.getDataFolder().toPath();live=root.resolve("exchange/live");settingsFile=root.resolve("exchange/settings.yml");ticketLedger=ledger;tickets=new PaperTickets(plugin,ledger,material,name);plugin.getServer().getPluginManager().registerEvents(this,plugin);load(null);}
 private boolean legacyPresent(){return plugin.getServer().getPluginManager().getPlugin("ArunikaDungeonExchange")!=null;}
 private boolean access(){return !closed&&!plugin.configurationBusy()&&!editing&&enabled&&catalog!=null&&token!=null&&!legacyPresent();}
 org.bukkit.inventory.ItemStack tokenTemplate(){return closed||editing||legacyPresent()||token==null?null:token.clone();}
 void ticketAppearance(String material,String name){tickets=new PaperTickets(plugin,ticketLedger,material,name);}
 boolean hasOperation(){return editing||!busy.isEmpty();}
 List<Reward> adminRewards(){return legacyPresent()||catalog==null?List.of():List.copyOf(catalog.rewards());}
 String status(){return status+(enabled?" | enabled":" | locked");}
 String diagnostics(){return status()+" | busy players="+busy.size()+" | worker queue="+worker.getQueue().size()+"/128 | editing="+editing;}
 private void main(Runnable r){if(!closed&&plugin.isEnabled())plugin.getServer().getScheduler().runTask(plugin,()->{if(!closed)r.run();});}
 @FunctionalInterface private interface Job<T>{T run()throws Exception;}
 private <T>void submit(Job<T> job,java.util.function.Consumer<T> ok,java.util.function.Consumer<Throwable> fail){try{worker.execute(()->{try{T value=job.run();main(()->ok.accept(value));}catch(Exception|LinkageError e){main(()->fail.accept(e));}});}catch(RejectedExecutionException e){fail.accept(e);}}
 private Map<String,Object> read(Path p)throws IOException{if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.size(p)>2_000_000)throw new IOException("Invalid file: "+p.getFileName());return codec.read(Files.readAllBytes(p));}
 private Loaded readCatalog()throws Exception{var s=read(settingsFile);return new Loaded(ExchangeCatalog.parse(read(live.resolve("config.yml")),read(live.resolve("rewards.yml")),s),Boolean.TRUE.equals(s.get("enabled"))&&Boolean.FALSE.equals(s.get("legacy-ownership")));}
 void load(CommandSender sender){if(plugin.configurationBusy()||editing||!busy.isEmpty()){if(sender!=null)sender.sendMessage("Exchange busy");return;}if(legacyPresent()){enabled=false;status="Legacy plugin present: original owns /dg";if(sender!=null)sender.sendMessage(status);return;}editing=true;enabled=false;submit(()->{ExchangeMigration.importOnce(root.getParent().resolve("ArunikaDungeonExchange"),live);var l=readCatalog();if(db==null)db=new ExchangeLedger(live.resolve("exchange.db"));return l;},l->{editing=false;try{apply(l);if(sender!=null)sender.sendMessage(status());}catch(RuntimeException e){enabled=false;status="Catalog rejected: "+e.getMessage();if(sender!=null)sender.sendMessage(status);}},e->{editing=false;enabled=false;status="Exchange unavailable: "+e.getMessage();plugin.getLogger().warning(status);if(sender!=null)sender.sendMessage(status);});}
 private void apply(Loaded l){if(l.catalog.token().isEmpty()){catalog=l.catalog;token=null;previews=Map.of();enabled=false;status="Fresh Exchange ready: hold currency and use /opdg token set";return;}ItemStack t=decode(l.catalog.token());t.setAmount(1);if(PaperLoot.hasTicketTag(t))throw new IllegalArgumentException("Ticket cannot be currency");Map<UUID,ItemStack> out=new HashMap<>();for(Reward r:l.catalog.rewards()){if(r.type()==Type.TICKET){out.put(r.id(),new ItemStack(Material.PAPER));continue;}try{ItemStack item=decode(r.item());if(PaperLoot.hasTicketTag(item))throw new IllegalArgumentException("Serialized ticket not allowed");if(r.type()==Type.ITEM&&item.isSimilar(t))throw new IllegalArgumentException("Reward cannot be currency token");out.put(r.id(),item);}catch(RuntimeException e){plugin.getLogger().warning("Reward "+r.key()+" unavailable: "+e.getMessage());}}catalog=l.catalog;token=t;previews=Map.copyOf(out);enabled=l.enabled;status="Catalog ready: "+(catalog.rewards().size()-1)+" legacy/custom rewards + universal ticket";}
 private static ItemStack decode(String b){ItemStack i=ItemStack.deserializeBytes(Base64.getDecoder().decode(b));if(i.getType().isAir()||!i.getType().isItem()||i.getAmount()<1||i.getAmount()>i.getMaxStackSize())throw new IllegalArgumentException("Invalid item template");return i;}
 private boolean allowed(Reward r){return ExchangeCatalog.allowed(catalog,r)&&previews.containsKey(r.id())&&(r.type()!=Type.PERMISSION||plugin.getServer().getPluginManager().isPluginEnabled("LuckPerms"));}
 private boolean eligible(Player p){return p!=null&&p.isOnline()&&!p.isDead()&&p.getGameMode()!=GameMode.CREATIVE&&p.getGameMode()!=GameMode.SPECTATOR&&p.hasPermission("arunika.dg.use")&&p.hasPermission("arunika.dungeon.exchange.test")&&plugin.session(p.getUniqueId()).isEmpty()&&plugin.queuedFloor(p.getUniqueId()).isEmpty()&&!plugin.inPrivateParty(p.getUniqueId());}
 private List<String> categories(){var c=new ArrayList<String>();c.add("All");catalog.rewards().stream().map(Reward::category).distinct().sorted().filter(s->!s.equals("All")).forEach(c::add);return c;}
 private void open(Player p,String cat,int page){if(!access()||!eligible(p)){p.sendMessage(status());return;}List<Reward> visible=catalog.rewards().stream().filter(r->r.enabled()&&(cat.equals("All")||cat.equals(r.category()))).toList();page=Math.max(0,Math.min(page,Math.max(0,(visible.size()-1)/45)));Menu h=new Menu(p.getUniqueId(),cat,page,null);h.inv=Bukkit.createInventory(h,54,Component.text("Arunika | Dungeon Exchange"));for(int i=page*45;i<Math.min(visible.size(),(page+1)*45);i++){Reward r=visible.get(i);int slot=i%45;h.slots.put(slot,r);ItemStack icon=previews.getOrDefault(r.id(),new ItemStack(Material.BARRIER)).clone();if(r.type()==Type.TICKET)icon=icon(Material.PAPER,"Universal Dungeon Ticket");var meta=icon.getItemMeta();List<Component> lore=new ArrayList<>();if(meta.lore()!=null)lore.addAll(meta.lore());lore.add(GuiTheme.lore("Cost: "+r.cost()+" Dungeon Token"));lore.add(GuiTheme.lore("Category: "+r.category()+" | "+(allowed(r)?"Click to review":"Locked")));meta.lore(lore);icon.setItemMeta(meta);h.inv.setItem(slot,icon);}for(int slot=45;slot<54;slot++)h.inv.setItem(slot,icon(Material.BLACK_STAINED_GLASS_PANE," "));h.inv.setItem(45,icon(Material.ARROW,"Previous page"));h.inv.setItem(49,icon(Material.COMPASS,"Category: "+cat));h.inv.setItem(53,icon(Material.ARROW,"Next page"));p.openInventory(h.inv);}
 private static ItemStack icon(Material m,String name){var i=new ItemStack(m);var meta=i.getItemMeta();meta.displayName(GuiTheme.name(name,m));i.setItemMeta(meta);return i;}
 private void confirm(Player p,Menu old,Reward r){Menu h=new Menu(p.getUniqueId(),old.category,old.page,r.id());h.slots.put(13,r);h.inv=Bukkit.createInventory(h,27,Component.text("Confirm: "+r.cost()+" tokens"));h.inv.setItem(13,previews.get(r.id()).clone());h.inv.setItem(11,icon(Material.LIME_CONCRETE,"Confirm purchase"));h.inv.setItem(15,icon(Material.RED_CONCRETE,"Cancel"));p.openInventory(h.inv);}
 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Menu h))return;boolean cancelled=e.isCancelled();e.setCancelled(true);if(cancelled)return;if(!(e.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(h.owner)||!access()||e.getRawSlot()<0||e.getRawSlot()>=h.inv.getSize()||e.getClick()!=ClickType.LEFT&&e.getClick()!=ClickType.RIGHT)return;int slot=e.getRawSlot();if(h.clickPending)return;h.clickPending=true; // one pending click per menu, open/close next tick
  plugin.getServer().getScheduler().runTask(plugin,()->{h.clickPending=false;if(!eligible(p)||p.getOpenInventory().getTopInventory().getHolder()!=h||!access())return;if(h.confirm!=null){if(slot==11){p.closeInventory();purchase(p,h.slots.get(13));}else if(slot==15)open(p,h.category,h.page);return;}if(slot==45)open(p,h.category,h.page-1);else if(slot==53)open(p,h.category,h.page+1);else if(slot==49){var c=categories();open(p,c.get((c.indexOf(h.category)+1)%c.size()),0);}else{Reward r=h.slots.get(slot);if(r!=null&&catalog.rewards().contains(r)&&allowed(r))confirm(p,h,r);}});}
 @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Menu)e.setCancelled(true);}
 private record InventoryPlan(ItemStack[] storage,ItemStack offhand){}
 private static ItemStack[] copy(ItemStack[] a){return Arrays.stream(a).map(i->i==null?null:i.clone()).toArray(ItemStack[]::new);}
 private boolean matches(ItemStack i){return i!=null&&!i.getType().isAir()&&token.isSimilar(i);}
 private InventoryPlan plan(Player p,int cost,ItemStack reward){var storage=copy(p.getInventory().getStorageContents());ItemStack off=p.getInventory().getItemInOffHand().clone();int left=cost;for(int i=0;i<storage.length&&left>0;i++)if(matches(storage[i])){int n=Math.min(left,storage[i].getAmount());left-=n;storage[i].setAmount(storage[i].getAmount()-n);if(storage[i].getAmount()==0)storage[i]=null;}if(left>0&&matches(off)){int n=Math.min(left,off.getAmount());left-=n;off.setAmount(off.getAmount()-n);if(off.getAmount()==0)off=new ItemStack(Material.AIR);}if(left>0)throw new IllegalStateException("Dungeon Token tidak cukup");if(reward!=null){int n=reward.getAmount();for(ItemStack i:storage)if(i!=null&&i.isSimilar(reward)){int add=Math.min(n,Math.max(0,i.getMaxStackSize()-i.getAmount()));i.setAmount(i.getAmount()+add);n-=add;}for(int j=0;j<storage.length&&n>0;j++)if(storage[j]==null||storage[j].getType().isAir()){ItemStack i=reward.clone();int add=Math.min(n,i.getMaxStackSize());i.setAmount(add);storage[j]=i;n-=add;}if(n>0)throw new IllegalStateException("Inventory penuh");}return new InventoryPlan(storage,off);}
 private ItemStack rewardItem(Reward r){return r.type()==Type.ITEM?previews.get(r.id()).clone():null;}
 private void purchase(Player p,Reward old){UUID id=p.getUniqueId();if(!access()||!eligible(p)||busy.contains(id)){p.sendMessage("Exchange unavailable/busy");return;}Reward r=catalog.rewards().stream().filter(x->x.equals(old)).findFirst().orElse(null);if(r==null||!allowed(r)){p.sendMessage("Reward changed or locked; reopen menu");return;}try{if(r.type()==Type.PERMISSION&&!ExchangePermission.available(id,r.grants().getFirst()))throw new IllegalStateException("Permission already owned or unavailable");plan(p,r.cost(),rewardItem(r));}catch(RuntimeException|LinkageError e){p.sendMessage(e.getMessage());return;}busy.add(id);String name=p.getName();submit(()->db.reserve(id,name,r),tx->debit(p,r,tx),e->failed(id,e));}
 private void debit(Player p,Reward r,ExchangeLedger.Tx tx){UUID id=tx.player();InventoryPlan plan;try{if(!access()||!eligible(p))throw new IllegalStateException("Player unavailable");if(r.type()==Type.PERMISSION&&!ExchangePermission.available(id,r.grants().getFirst()))throw new IllegalStateException("Permission now exists");plan=plan(p,r.cost(),rewardItem(r));}catch(RuntimeException|LinkageError e){submit(()->{db.cancel(tx);return null;},v->{busy.remove(id);tell(id,"Purchase cancelled: "+e.getMessage());},x->failed(id,x));return;}
  // From this point, never auto-refund: player save and SQLite cannot be one atomic transaction.
  try{p.getInventory().setStorageContents(plan.storage());p.getInventory().setItemInOffHand(plan.offhand());p.saveData();}catch(RuntimeException e){failed(id,e);return;}
  submit(()->{db.debit(tx);return null;},v->{if(r.type()==Type.ITEM)finish(tx,"Item granted with debit");else if(r.type()==Type.TICKET)issueTicket(tx);else try{ExchangePermission.grant(id,r.grants().getFirst()).whenComplete((x,e)->main(()->{if(e==null)finish(tx,"Temporary permission granted");else failed(id,e);}));}catch(RuntimeException|LinkageError e){failed(id,e);}},e->failed(id,e));}
 private void issueTicket(ExchangeLedger.Tx tx){submit(()->ticketLedger.issueForExchange(tx.id(),tx.player()),ticket->{Player p=Bukkit.getPlayer(tx.player());try{if(p!=null&&eligible(p))tickets.deliver(p,ticket);tell(tx.player(),"Ticket serial: "+ticket.serial()+" | /dg claim "+ticket.serial());finish(tx,"Ticket serial "+ticket.serial()+" (claim available if pending)");}catch(Exception e){failed(tx.player(),e);}},e->failed(tx.player(),e));}
 private void finish(ExchangeLedger.Tx tx,String detail){submit(()->{db.delivered(tx,detail);return null;},v->{busy.remove(tx.player());tell(tx.player(),"Exchange berhasil.");},e->failed(tx.player(),e));}
 private void failed(UUID id,Throwable e){busy.remove(id);tell(id,"Exchange: "+e.getMessage()+". Jika transaksi tertunda hubungi admin.");plugin.getLogger().warning("Exchange transaction: "+e);}
 private void tell(UUID id,String msg){Player p=Bukkit.getPlayer(id);if(p!=null)p.sendMessage(msg);}
 private void claim(Player p,String serial){if(!access()||!eligible(p)||!busy.add(p.getUniqueId()))return;try{UUID id=UUID.fromString(serial);var t=ticketLedger.claim(id,p.getUniqueId());tickets.deliver(p,t);}catch(Exception e){p.sendMessage("Claim: "+e.getMessage());}finally{busy.remove(p.getUniqueId());}}
 private void edit(CommandSender sender,String[] a){if(plugin.configurationBusy()||legacyPresent()||editing||!busy.isEmpty()||catalog==null){sender.sendMessage("Exchange busy or not imported");return;}if(a.length<1)return;final String hand;try{if(a[0].equals("addhand")||a[0].equals("token")){if(!(sender instanceof Player p))throw new IllegalArgumentException("Player required");ItemStack item=p.getInventory().getItemInMainHand().clone();if(item.getType().isAir()||PaperLoot.hasTicketTag(item))throw new IllegalArgumentException("Hold a non-ticket item");if(a[0].equals("token"))item.setAmount(1);hand=Base64.getEncoder().encodeToString(item.serializeAsBytes());}else hand=null;}catch(RuntimeException e){sender.sendMessage(e.getMessage());return;}editing=true;enabled=false;submit(()->{
  Path cfg=live.resolve("config.yml"),rewards=live.resolve("rewards.yml");var c=read(cfg);var d=read(rewards);var s=read(settingsFile);Path dest;Map<String,Object> data;
  switch(a[0]){
   case "token"->{if(a.length!=2||!a[1].equals("set"))throw new IllegalArgumentException("token set");var t=ExchangeCatalog.map(c.get("token"));t.put("template-base64",hand);t.remove("fresh-token-unset");c.put("token",t);dest=cfg;data=c;}
   case "exchange"->{if(a.length!=2||!Set.of("on","off").contains(a[1]))throw new IllegalArgumentException("exchange on|off");if(a[1].equals("on")&&ExchangeCatalog.map(c.get("token")).get("template-base64").equals(""))throw new IllegalStateException("Set token first: /opdg token set");s.put("enabled",a[1].equals("on"));s.put("legacy-ownership",false);dest=settingsFile;data=s;}
   case "ticket"->{if(a.length!=3||!Set.of("on","off").contains(a[2]))throw new IllegalArgumentException("ticket <cost> <on|off>");s.put("ticket-exchange",Map.of("cost",Integer.parseInt(a[1]),"enabled",a[2].equals("on")));dest=settingsFile;data=s;}
   default->{var rs=ExchangeCatalog.map(d.get("rewards"));if(a.length<2||!a[1].matches("[a-zA-Z0-9_-]{1,48}"))throw new IllegalArgumentException("Invalid key");String key=a[1];if(a[0].equals("addhand")){if(a.length<4||rs.containsKey(key))throw new IllegalArgumentException("addhand <new-key> <cost> <category>");var m=new LinkedHashMap<String,Object>();m.put("id",UUID.randomUUID().toString());m.put("item-base64",hand);m.put("cost",Integer.parseInt(a[2]));m.put("stock",-1);m.put("limit",0);m.put("enabled",true);m.put("revision",1);m.put("type","ITEM");m.put("bundle-item",true);m.put("category",String.join(" ",Arrays.copyOfRange(a,3,a.length)));m.put("commands",List.of());rs.put(key,m);}else{var m=ExchangeCatalog.map(rs.get(key));switch(a[0]){case "cost"->{if(a.length!=3)throw new IllegalArgumentException("cost <key> <cost>");m.put("cost",Integer.parseInt(a[2]));}case "category"->{if(a.length<3)throw new IllegalArgumentException("category <key> <name>");m.put("category",String.join(" ",Arrays.copyOfRange(a,2,a.length)));}case "enable"->{if(a.length!=3||!Set.of("true","false").contains(a[2]))throw new IllegalArgumentException("enable <key> true|false");m.put("enabled",Boolean.parseBoolean(a[2]));}default->throw new IllegalArgumentException("Unknown editor");}m.put("revision",Math.addExact(((Number)m.get("revision")).intValue(),1));rs.put(key,m);}d.put("rewards",rs);dest=rewards;data=d;}
  }
  var next=ExchangeCatalog.parse(c,d,s);byte[] bytes=codec.write(data);if(bytes.length>2_000_000)throw new IOException("File too large");Path backup=root.resolve("backups/exchange-edit-"+UUID.randomUUID());Files.createDirectories(backup);Files.copy(dest,backup.resolve(dest.getFileName()));Path tmp=Files.createTempFile(dest.getParent(),".exchange-",".tmp");try{Files.write(tmp,bytes);try(var chan=java.nio.channels.FileChannel.open(tmp,StandardOpenOption.WRITE)){chan.force(true);}Files.move(tmp,dest,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(tmp);}return new Loaded(next,Boolean.TRUE.equals(s.get("enabled"))&&Boolean.FALSE.equals(s.get("legacy-ownership")));},l->{editing=false;try{apply(l);sender.sendMessage("Exchange edit saved; "+status());}catch(RuntimeException e){enabled=false;sender.sendMessage("Exchange locked: "+e.getMessage());}},e->{editing=false;enabled=false;sender.sendMessage("Edit rejected; /opdg reload to retry: "+e.getMessage());});}
 void command(CommandSender sender,boolean admin,String[] a){if(legacyPresent()){sender.sendMessage("Legacy Exchange remains owner; use its commands.");return;}if(admin){if(!sender.hasPermission("arunika.dg.admin")&&!sender.hasPermission("arunika.dungeon.admin")){sender.sendMessage("No permission");return;}if(a.length==0||a[0].equals("status")){sender.sendMessage(status());return;}if(a[0].equals("reload")){load(sender);return;}if(a[0].equals("rewards")&&catalog!=null){catalog.rewards().forEach(r->sender.sendMessage(r.key()+" | "+r.type()+" | "+r.cost()+" tokens | "+r.category()+" | "+(r.enabled()?"enabled":"disabled")));return;}if(a[0].equals("tx")&&db!=null){if(plugin.configurationBusy()||editing||!busy.isEmpty()){sender.sendMessage("Exchange busy");return;}if(a.length==2&&a[1].equals("list")){submit(()->db.pending(),ls->{if(ls.isEmpty())sender.sendMessage("No pending ADG transactions");else ls.forEach(sender::sendMessage);},e->sender.sendMessage(e.getMessage()));return;}if(a.length==4&&a[1].equals("resolve")&&Set.of("no-debit","delivered").contains(a[3])&&sender.isOp()){editing=true;submit(()->{db.resolve(UUID.fromString(a[2]),a[3].equals("no-debit"));return null;},v->{editing=false;sender.sendMessage("Transaction resolved; no automatic delivery/refund.");},e->{editing=false;sender.sendMessage(e.getMessage());});return;}}if(a[0].equals("exchange")&&!sender.hasPermission("arunika.dg.toggle")){sender.sendMessage("No toggle permission");return;}if(Set.of("token","exchange","ticket","addhand","cost","category","enable").contains(a[0])){edit(sender,a);return;}sender.sendMessage("/opdg status|reload|rewards|token set|exchange on/off|ticket <cost> <on/off>|addhand <key> <cost> <category>|cost <key> <cost>|category <key> <name>|enable <key> true/false|tx list|tx resolve <id> <no-debit|delivered>");return;}
  if(!(sender instanceof Player p)||(!p.hasPermission("arunika.dg.use")||!p.hasPermission("arunika.dungeon.exchange.test"))){sender.sendMessage("Player/staging permission required");return;}if(a.length==2&&a[0].equals("claim")){claim(p,a[1]);return;}if(a.length==0)open(p,"All",0);else sender.sendMessage("/dg | /dg claim <serial>");}
 private void closeDatabase(){if(db!=null)try{db.close();}catch(Exception e){plugin.getLogger().warning("Exchange DB close: "+e);}}
 @Override public void close(){closed=true;enabled=false;try{HandlerList.unregisterAll(this);for(Player p:Bukkit.getOnlinePlayers())if(p.getOpenInventory().getTopInventory().getHolder() instanceof Menu)p.closeInventory();}finally{worker.shutdown();}}
}
